module election_solver(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [2:0] k,\n    input [4:0] m,\n    input [4:0] a,\n    input [4:0] vote_count [0:7],\n    input [4:0] last_vote [0:7],\n    output reg [1:0] result [0:7],\n    output reg done\n);\n    function automatic [4:0] compute_cost;\n        input [4:0] v_j, v_i, last_j, last_i, a;\n        reg [4:0] need1, need2;\n        begin\n            if (v_j > v_i) \n                compute_cost = 5'd0;\n            else if (v_j == v_i) \n                if (last_j < last_i)\n                    compute_cost = 5'd0;\n                else\n                    compute_cost = 5'd1;\n            else begin\n                need1 = v_i - v_j + 5'd1;\n                if ((v_i - v_j == 5'd1) && (last_i > a))\n                    need2 = 5'd1;\n                else\n                    need2 = need1;\n                compute_cost = (need1 < need2) ? need1 : need2;\n            end\n        end\n    endfunction\n    \n    // States\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] PROCESS = 2'd1;\n    localparam [1:0] FINISH  = 2'd2;\n    reg [1:0] state;\n    \n    reg [1:0] next_result [0:7];\n    integer i, j, idx, p, q, s;\n    reg [4:0] costs [0:6];\n    reg [4:0] temp;\n    reg [4:0] total_cost;\n    reg [4:0] R;\n    reg [4:0] count;\n    \n    always @(*) begin\n        R = m - a;\n        for (i = 0; i < 8; i = i + 1) begin\n            if (i < n) begin\n                idx = 0;\n                for (j = 0; j < 8; j = j + 1) begin\n                    if ((j < n) && (j != i)) begin\n                        costs[idx] = compute_cost(\n                            vote_count[j], vote_count[i],\n                            last_vote[j], last_vote[i], a);\n                        idx = idx + 1;\n                    end\n                end\n                for (p = 0; p < idx - 1; p = p + 1) begin\n                    for (q = 0; q < idx - 1 - p; q = q + 1) begin\n                        if (costs[q] > costs[q + 1]) begin\n                            temp = costs[q];\n                            costs[q] = costs[q + 1];\n                            costs[q + 1] = temp;\n                        end\n                    end\n                end\n                total_cost = 5'd0;\n                for (s = 0; s < k; s = s + 1) begin\n                    if (s < idx)\n                        total_cost = total_cost + costs[s];\n                end\n                if (total_cost > R)\n                    next_result[i] = 2'd1;\n                else begin\n                    if (vote_count[i] + R == 5'd0)\n                        next_result[i] = 2'd3;\n                    else begin\n                        count = 5'd0;\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if ((j < n) && (j != i)) begin\n                                if (vote_count[j] > (vote_count[i] + R))\n                                    count = count + 5'd1;\n                                else if ((vote_count[j] == (vote_count[i] + R)) && (last_vote[j] < (m - 5'd1)))\n                                    count = count + 5'd1;\n                            end\n                        end\n                        if (count < k)\n                            next_result[i] = 2'd2;\n                        else\n                            next_result[i] = 2'd3;\n                    end\n                end\n            end else\n                next_result[i] = 2'd0;\n        end\n    end\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            for (i = 0; i < 8; i = i + 1) begin\n                result[i] <= 2'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        for (i = 0; i < 8; i = i + 1) begin\n                            result[i] <= next_result[i];\n                        end\n                        state <= FINISH;\n                    end\n                end\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule